<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --blue:#3861FB;--navy:#0D1421;--gray:#808A9D;--green:#16c784;--red:#ea3943;
  --bg:#fff;--bg-alt:#f8f9fa;--bg-hover:#f0f2f5;--border:#e8eaed;--text:#0D1421;--text-sec:#808A9D;
}
html{font-size:14px;-webkit-font-smoothing:antialiased}
body{font-family:'Inter',system-ui,-apple-system,sans-serif;background:var(--bg);color:var(--text);line-height:1.5}
a{color:var(--blue);text-decoration:none}
a:hover{text-decoration:underline}
button{font-family:inherit;cursor:pointer}

/* Utility */
.tabular{font-variant-numeric:tabular-nums}
.green{color:var(--green)}.red{color:var(--red)}.blue{color:var(--blue)}.gray{color:var(--gray)}

/* Header */
.site-header{border-bottom:1px solid var(--border);background:var(--bg);position:sticky;top:0;z-index:50}
.header-inner{max-width:1400px;margin:0 auto;padding:0 24px;display:flex;align-items:center;height:56px;gap:24px}
.logo{font-size:18px;font-weight:700;color:var(--navy);white-space:nowrap;display:flex;align-items:center;gap:6px}
.logo svg{flex-shrink:0}
.nav-links{display:flex;gap:4px;flex:1;overflow-x:auto}
.nav-links a{padding:6px 12px;border-radius:6px;font-size:13px;font-weight:500;color:var(--navy);white-space:nowrap;transition:background .15s}
.nav-links a:hover{background:var(--bg-hover);text-decoration:none}
.nav-links a.active{background:#eef1ff;color:var(--blue)}
.header-actions{display:flex;align-items:center;gap:8px;flex-shrink:0}
.btn-login{padding:6px 16px;border-radius:6px;font-size:13px;font-weight:600;color:var(--blue);border:1.5px solid var(--blue);background:transparent;transition:all .15s}
.btn-login:hover{background:var(--blue);color:#fff}
.btn-signup{padding:6px 16px;border-radius:6px;font-size:13px;font-weight:600;color:#fff;background:var(--blue);border:1.5px solid var(--blue);transition:all .15s}
.btn-signup:hover{background:#2950e0}

/* Top Metrics Bar */
.metrics-bar{background:var(--bg-alt);border-bottom:1px solid var(--border)}
.metrics-inner{max-width:1400px;margin:0 auto;padding:10px 24px;display:flex;gap:32px;align-items:center;flex-wrap:wrap}
.metric{display:flex;align-items:center;gap:6px;font-size:13px}
.metric-label{color:var(--gray);font-weight:500}
.metric-value{font-weight:600;color:var(--navy)}
.metric-change{font-size:12px;font-weight:600}

/* Promo Banner */
.promo-section{border-bottom:1px solid var(--border);overflow:hidden;position:relative;background:linear-gradient(135deg,#f0f4ff 0%,#fff 100%)}
.promo-track{display:flex;transition:transform .4s ease}
.promo-slide{min-width:100%;padding:14px 24px;display:flex;align-items:center;justify-content:center;gap:12px;font-size:14px;font-weight:500}
.promo-slide .cta{background:var(--blue);color:#fff;padding:5px 16px;border-radius:20px;font-size:12px;font-weight:600;transition:opacity .15s}
.promo-slide .cta:hover{opacity:.9}
.promo-dots{display:flex;justify-content:center;gap:6px;padding-bottom:8px}
.promo-dot{width:6px;height:6px;border-radius:50%;background:var(--border);border:none;transition:background .15s}
.promo-dot.active{background:var(--blue)}

/* AI Alerts */
.ai-bar{border-bottom:1px solid var(--border);background:var(--bg)}
.ai-inner{max-width:1400px;margin:0 auto;padding:12px 24px}
.ai-prompt{display:flex;align-items:center;gap:10px;margin-bottom:10px}
.ai-badge{background:linear-gradient(135deg,#6366f1,#8b5cf6);color:#fff;padding:3px 10px;border-radius:12px;font-size:11px;font-weight:700;letter-spacing:.3px;flex-shrink:0}
.ai-input{flex:1;padding:8px 14px;border:1px solid var(--border);border-radius:8px;font-size:13px;background:var(--bg-alt);color:var(--navy);outline:none;transition:border .15s}
.ai-input:focus{border-color:var(--blue)}
.ai-suggestions{display:flex;gap:8px;flex-wrap:wrap}
.ai-chip{padding:5px 12px;border:1px solid var(--border);border-radius:20px;font-size:12px;color:var(--text-sec);background:var(--bg);cursor:pointer;transition:all .15s;white-space:nowrap}
.ai-chip:hover{border-color:var(--blue);color:var(--blue)}

/* Filter Tabs */
.filter-section{border-bottom:1px solid var(--border)}
.filter-inner{max-width:1400px;margin:0 auto;padding:12px 24px}
.cat-tabs{display:flex;gap:4px;margin-bottom:8px;overflow-x:auto;padding-bottom:2px}
.cat-tab{padding:7px 16px;border-radius:8px;font-size:13px;font-weight:600;border:none;background:transparent;color:var(--gray);transition:all .15s;white-space:nowrap}
.cat-tab:hover{background:var(--bg-hover);color:var(--navy)}
.cat-tab.active{background:var(--blue);color:#fff}
.cat-tab.active:hover{background:#2950e0}
.network-tabs{display:flex;gap:4px;overflow-x:auto;padding-bottom:2px}
.net-tab{padding:5px 14px;border-radius:6px;font-size:12px;font-weight:500;border:1px solid var(--border);background:var(--bg);color:var(--gray);transition:all .15s;white-space:nowrap}
.net-tab:hover{border-color:var(--blue);color:var(--blue)}
.net-tab.active{border-color:var(--blue);color:var(--blue);background:#eef1ff}

/* Table Controls */
.table-controls{max-width:1400px;margin:0 auto;padding:10px 24px;display:flex;align-items:center;gap:8px}
.sort-btn{padding:5px 12px;border-radius:6px;font-size:12px;font-weight:600;border:1px solid var(--border);background:var(--bg);color:var(--navy);display:flex;align-items:center;gap:4px;transition:all .15s}
.sort-btn:hover{border-color:var(--blue);color:var(--blue)}
.sort-btn.active{border-color:var(--blue);color:var(--blue);background:#eef1ff}
.sort-btn svg{width:12px;height:12px}
.ctrl-spacer{flex:1}
.ctrl-btn{padding:5px 12px;border-radius:6px;font-size:12px;font-weight:500;border:1px solid var(--border);background:var(--bg);color:var(--gray);display:flex;align-items:center;gap:4px;transition:all .15s}
.ctrl-btn:hover{border-color:var(--blue);color:var(--blue)}
.ctrl-btn.active{border-color:var(--blue);color:var(--blue);background:#eef1ff}

/* Dropdown Panel */
.dropdown-panel{position:absolute;top:100%;right:0;margin-top:4px;background:#fff;border:1px solid var(--border);border-radius:10px;box-shadow:0 8px 30px rgba(0,0,0,.12);padding:8px 0;min-width:200px;z-index:40;display:none}
.dropdown-panel.open{display:block}
.dropdown-item{padding:8px 16px;font-size:13px;display:flex;align-items:center;gap:8px;cursor:pointer;transition:background .1s}
.dropdown-item:hover{background:var(--bg-hover)}
.dropdown-item input[type=checkbox]{accent-color:var(--blue);width:15px;height:15px}
.dropdown-item label{cursor:pointer;flex:1}

/* Filter Panel */
.filter-panel{max-width:1400px;margin:0 auto;padding:0 24px;max-height:0;overflow:hidden;transition:max-height .3s ease}
.filter-panel.open{max-height:200px;padding:12px 24px}
.filter-panel-inner{display:flex;gap:16px;flex-wrap:wrap;align-items:center}
.filter-field{display:flex;flex-direction:column;gap:4px}
.filter-field label{font-size:11px;font-weight:600;color:var(--gray);text-transform:uppercase;letter-spacing:.5px}
.filter-field input,.filter-field select{padding:6px 10px;border:1px solid var(--border);border-radius:6px;font-size:13px;outline:none;transition:border .15s}
.filter-field input:focus,.filter-field select:focus{border-color:var(--blue)}

/* Crypto Table */
.table-wrap{max-width:1400px;margin:0 auto;padding:0 24px;overflow-x:auto}
.crypto-table{width:100%;border-collapse:collapse;font-size:13px;min-width:1100px}
.crypto-table th{padding:10px 10px;font-size:11px;font-weight:600;color:var(--gray);text-transform:uppercase;letter-spacing:.5px;text-align:left;border-bottom:1px solid var(--border);white-space:nowrap;position:sticky;top:56px;background:var(--bg);z-index:10}
.crypto-table th.right,.crypto-table td.right{text-align:right}
.crypto-table td{padding:10px 10px;border-bottom:1px solid var(--border);vertical-align:middle;white-space:nowrap}
.crypto-table tbody tr{transition:background .1s}
.crypto-table tbody tr:hover{background:var(--bg-hover)}
.rank-cell{color:var(--gray);font-weight:500;width:40px}
.name-cell{display:flex;align-items:center;gap:8px;min-width:160px}
.coin-icon{width:24px;height:24px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;color:#fff;flex-shrink:0}
.coin-name{font-weight:600;color:var(--navy)}
.coin-symbol{color:var(--gray);font-size:12px;margin-left:2px}
.pct{font-weight:600;font-size:12px}
.mcap{font-weight:500}
.vol{font-weight:500;color:var(--gray)}
.supply{color:var(--gray);font-size:12px}
.sparkline{width:120px;height:36px}

/* Index Row */
.index-row{background:var(--bg-alt);border-bottom:2px solid var(--border)}
.index-row:hover{background:var(--bg-alt)}
.index-label{font-size:12px;font-weight:600;color:var(--blue)}

/* Pagination */
.pagination{max-width:1400px;margin:0 auto;padding:16px 24px;display:flex;align-items:center;justify-content:center;gap:4px}
.page-btn{width:36px;height:36px;border-radius:8px;border:1px solid var(--border);background:var(--bg);font-size:13px;font-weight:500;color:var(--navy);display:flex;align-items:center;justify-content:center;transition:all .15s}
.page-btn:hover{border-color:var(--blue);color:var(--blue)}
.page-btn.active{background:var(--blue);color:#fff;border-color:var(--blue)}
.page-info{font-size:13px;color:var(--gray);margin-left:16px}

/* Market Summary */
.summary-section{max-width:1400px;margin:0 auto;padding:24px}
.summary-card{background:var(--bg-alt);border-radius:12px;padding:24px;border:1px solid var(--border)}
.summary-card h2{font-size:18px;font-weight:700;margin-bottom:12px}
.summary-card p{font-size:14px;line-height:1.7;color:#4a5568}
.summary-card p strong{color:var(--navy)}
.read-more-btn{display:inline-block;margin-top:8px;font-size:13px;font-weight:600;color:var(--blue);background:none;border:none;cursor:pointer}
.read-more-btn:hover{text-decoration:underline}
.summary-extra{max-height:0;overflow:hidden;transition:max-height .3s ease}
.summary-extra.open{max-height:200px}

/* Info Content */
.info-section{max-width:1400px;margin:0 auto;padding:0 24px 24px}
.info-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}
.info-block h3{font-size:16px;font-weight:700;margin-bottom:8px}
.info-block p{font-size:13px;line-height:1.7;color:#4a5568}

/* Footer */
.site-footer{background:var(--navy);color:#ccc;padding:40px 24px;margin-top:24px}
.footer-inner{max-width:1400px;margin:0 auto;display:grid;grid-template-columns:repeat(4,1fr);gap:32px}
.footer-col h4{font-size:13px;font-weight:700;color:#fff;margin-bottom:12px;text-transform:uppercase;letter-spacing:.5px}
.footer-col a{display:block;font-size:13px;color:#aab;margin-bottom:6px;transition:color .15s}
.footer-col a:hover{color:#fff;text-decoration:none}
.footer-bottom{max-width:1400px;margin:24px auto 0;padding-top:20px;border-top:1px solid rgba(255,255,255,.1);text-align:center;font-size:12px;color:#667}

/* Responsive */
@media(max-width:768px){
  .header-inner{padding:0 12px;gap:12px}
  .nav-links{display:none}
  .metrics-inner{gap:16px;padding:8px 12px}
  .ai-inner{padding:10px 12px}
  .filter-inner{padding:8px 12px}
  .table-controls{padding:8px 12px}
  .table-wrap{padding:0 12px}
  .pagination{padding:12px}
  .summary-section,.info-section{padding:16px 12px}
  .info-grid{grid-template-columns:1fr}
  .footer-inner{grid-template-columns:1fr 1fr;gap:20px}
  .promo-slide{padding:10px 12px;font-size:13px}
}

/* Scrollbar */
::-webkit-scrollbar{height:6px;width:6px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{background:#ccc;border-radius:3px}
::-webkit-scrollbar-thumb:hover{background:#aaa}

/* Animations */
@keyframes fadeIn{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:translateY(0)}}
.crypto-table tbody tr{animation:fadeIn .2s ease}
</style>
</head>
