// ========== FORMATTING ==========
function fmtPrice(p){
  if(p>=1000) return '$'+p.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
  if(p>=1) return '$'+p.toFixed(2);
  if(p>=0.01) return '$'+p.toFixed(4);
  if(p>=0.0001) return '$'+p.toFixed(6);
  return '$'+p.toFixed(8);
}
function fmtMcap(v){
  if(v>=1e12) return '$'+(v/1e12).toFixed(2)+'T';
  if(v>=1e9) return '$'+(v/1e9).toFixed(2)+'B';
  if(v>=1e6) return '$'+(v/1e6).toFixed(2)+'M';
  return '$'+v.toLocaleString();
}
function fmtVol(v){
  if(v>=1e9) return '$'+(v/1e9).toFixed(2)+'B';
  if(v>=1e6) return '$'+(v/1e6).toFixed(2)+'M';
  return '$'+v.toLocaleString();
}
function fmtSupply(v,s){
  if(v>=1e12) return (v/1e12).toFixed(2)+'T '+s;
  if(v>=1e9) return (v/1e9).toFixed(2)+'B '+s;
  if(v>=1e6) return (v/1e6).toFixed(2)+'M '+s;
  return v.toLocaleString()+' '+s;
}
function pctClass(v){return v>=0?'green':'red'}
function pctStr(v){return (v>=0?'+':'')+v.toFixed(2)+'%'}

// ========== SPARKLINE SVG ==========
function makeSparkline(seed,positive){
  const pts=[];let y=18;
  for(let i=0;i<14;i++){
    const delta=(Math.sin(seed*i*7.3+3.7)*8+(positive?1:-0.5)*2)*(1-i*0.04);
    y=Math.max(2,Math.min(34,18-delta));
    pts.push(`${i*9},${y}`);
  }
  const color=positive?'#16c784':'#ea3943';
  return `<svg class="sparkline" viewBox="0 0 126 36" fill="none"><polyline points="${pts.join(' ')}" stroke="${color}" stroke-width="1.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
}

